def main():
    ap=argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument('--snapshot',type=Path,required=True,help='verified pinned HF snapshot; helper/config/tokenizer must be present')
    ap.add_argument('--model',help='optional unquantized MLX bf16 copy; default snapshot')
    ap.add_argument('--out',type=Path,required=True,help='fixture JSON; choose a separate path with --prepare-only')
    ap.add_argument('--work-dir',type=Path,help='raw create receipts and example; default beside output')
    ap.add_argument('--prepare-only',action='store_true')
    a=ap.parse_args()
    S=a.snapshot.expanduser().resolve()
    if S.name!='5ec9e5fd2f80a6fff386779b1e5ac7e389971889':
        ap.error('snapshot must be the pinned openjev/openjev revision 5ec9e5fd…')
    a.out=a.out.expanduser().resolve();a.out.parent.mkdir(parents=True,exist_ok=True)
    R=(a.work_dir or a.out.parent/('.'+a.out.stem+'-work')).expanduser().resolve();R.mkdir(parents=True,exist_ok=True)
    a.model=str(Path(a.model).expanduser().resolve()) if a.model else str(S)
    os.environ.update(HF_HUB_OFFLINE='1',HF_HUB_DISABLE_XET='1',TOKENIZERS_PARALLELISM='false')
    settings={'READOUT_T':'0.85','READOUT_NOUL_T':'1.829074','READOUT_NOUL_BIAS':'0','READOUT_TARGETED':'1','READOUT_INSTR_STYLE':'pyrepr','READOUT_PERMS':'1','SHIM_STAGGER':'1','SHIM_PAD':'0','SHIM_COMPACT':'0','SHIM_LAYOUT':'','SHIM_LOOP_BREAK':'0'}
    os.environ.update(settings,TOKENIZER=str(S),SHIM_MODEL='openjev/openjev')
    helper=S/'helper/shim.py';hsha=hashlib.sha256(helper.read_bytes()).hexdigest()
    assert hsha=='81a22f1b1b8912a465059207ef9f60b7c6c16b4de6372305d867efbe38a1987a'
    spec=importlib.util.spec_from_file_location('shim',helper);shim=importlib.util.module_from_spec(spec);spec.loader.exec_module(shim)
    from transformers import AutoTokenizer
    tok=AutoTokenizer.from_pretrained(S,local_files_only=True)
    letters=shim.LETTERS
    encoded=[tok.encode(L,add_special_tokens=False) for L in letters]
    assert all(len(x)==1 for x in encoded) and len({x[0] for x in encoded})==52
    assert shim.letter_ids()==dict(zip(letters,[x[0] for x in encoded]))
    assert shim.TARGETED and shim.PERMS==1 and shim.TEMP==0.85 and shim.NOUL_T==1.829074
    calls=[];observations=[];active_id=None;prepare=a.prepare_only
    Obj=types.SimpleNamespace
    def ids_for(messages):
        ids=tok.apply_chat_template(messages,tokenize=True,add_generation_prompt=True,enable_thinking=False)
        return ids['input_ids'] if hasattr(ids,'input_ids') else ids
    def create(model=None,max_tokens=1,temperature=0,logprobs=False,messages=None,extra_body=None,**kw):
        eb=extra_body or {};want=eb.get('logprob_token_ids') or eb.get('allowed_token_ids')
        assert want and len(messages)==1 and isinstance(messages[0]['content'],str)
        assert eb['chat_template_kwargs']['enable_thinking'] is False
        ids=ids_for(messages);start=time.monotonic()
        if prepare:
            vals=[0.0]*len(want);raw=[0.0]*len(want);full_id=want[0];scale={}
        else:
            logits=MLX_MODEL(mx.array(ids)[None])[0,-1].astype(mx.float32)
            lp=logits-mx.logsumexp(logits,axis=-1)
            vals=[float(lp[i]) for i in want];mx.eval(logits)
            raw=[float(logits[i]) for i in want];full_id=int(mx.argmax(logits))
            scale={'logits_min':float(mx.min(logits)),'logits_max':float(mx.max(logits)),
                   'finite':bool(mx.all(mx.isfinite(logits))),'mlx_peak_memory_bytes':mx.get_peak_memory()}
            assert scale['finite'] and np.isfinite(vals).all()
        rec={'id':active_id,'ids':ids,'slot':len(ids)-1,'tokens':len(ids),'label_ids':want,
             'composed_user_text':messages[0]['content'],'raw_logprobs':vals,'raw_logits':raw,
             'full_vocab_argmax_id':full_id,'full_vocab_argmax_text':tok.decode([full_id]),
             'wall_seconds_contended':time.monotonic()-start,**scale}
        calls.append(rec)
        if not prepare:
            with (R/'oracle-create.jsonl').open('a') as f:f.write(json.dumps(rec,ensure_ascii=False)+'\n')
        top=[Obj(token=f'token_id:{i}',logprob=v) for i,v in zip(want,vals)]
        return Obj(choices=[Obj(logprobs=Obj(content=[Obj(top_logprobs=top)]))],usage=Obj(prompt_tokens=len(ids)))
    shim.client=Obj(chat=Obj(completions=Obj(create=create)),base_url='mlx://openjev/openjev-bf16')
