    def observe(state,instructions,options):
        p,n=original_readout(state,instructions,options)
        observations.append({'instructions_rendered':instructions,'options':[{'key':k,'desc':d} for k,d in options],'p_author':p})
        return p,n
    shim.readout=observe
    reqs=json.loads(EMBEDDED_REQUESTS)
    fx={'schema':'coreai-letter-fixtures/1','license':'CC BY-NC 4.0','label_style':'bare','template':'chat','temperature':0.85,'noul':{'t':1.829074,'bias':0},
        'source':{'hf_id':'openjev/openjev','revision':S.name,'helper_sha256':hsha,'shim_mlx_sha256':hashlib.sha256((S/'helper/shim_mlx.py').read_bytes()).hexdigest(),'settings':settings,'oracle':'A: author helper over unquantized bf16 weights via mlx-lm','model_path':a.model},
        'letters':letters,'letter_ids':[x[0] for x in encoded],'requests':reqs,'rows':[],
        'state_note':'With its optional transforms off, with_image serializes a dict using json.dumps(ensure_ascii=False), including the text key of a {"text": ...} object; plain strings remain unchanged.',
        'helper_version':shim.VERSION,'result':'PREPARED' if prepare else 'RUNNING'}
    def save():
        p=a.out;t=p.with_suffix('.tmp');t.write_text(json.dumps(fx,indent=1,ensure_ascii=False,allow_nan=False)+'\n');t.replace(p)
    if not prepare:
        import mlx.core as mx
        from mlx_lm import load
        print('loading bf16 MLX snapshot',a.model,flush=True)
        MLX_MODEL,_=load(a.model)
        from mlx.utils import tree_flatten
        weights=tree_flatten(MLX_MODEL.parameters())
        dtypes={str(v.dtype).replace('mlx.core.', '') for k,v in weights}
        fx['model_load']={'dtype_name_normalization':'str(dtype).replace(mlx.core., empty), accepting mlx.core.bfloat16', 'dtypes':sorted(dtypes),'parameters':sum(v.size for k,v in weights),'tensor_count':len(weights),'vision_keys': [k for k,v in weights if 'visual' in k],'mtp_keys':[k for k,v in weights if k.startswith('mtp')], 'quantized_layers':sum('Quantized' in type(m).__name__ for m in MLX_MODEL.modules())}
        save();print('loaded model',fx['model_load'],flush=True)
        assert 'bfloat16' in dtypes and fx['model_load']['quantized_layers']==0
        assert not fx['model_load']['vision_keys'] and not fx['model_load']['mtp_keys']
        # The literal card request is separate because its state is shorter than the fixture floor.
        st=shim.with_image('Customer message: I was charged twice for my order last week and nobody has replied.')
        example={}
        for kind,q in [('choice',{'type':'choice','instructions':'Which team should handle this?','criteria':dict.fromkeys(['billing','shipping','technical'])}),('noul',{'type':'noul','instructions':'Is the customer angry?'})]:
            active_id='card-example-'+kind
            ans,n=shim.ANSWER[kind](st,q);example[kind]={'answer':ans,'tokens':n,'readout':observations[-1],'create':calls[-1]}
        (R/'card-example.json').write_text(json.dumps(example,indent=2)+'\n')
        assert example['choice']['answer']['choice']=='billing',example
        print('card example',example['choice']['answer'],example['noul']['answer'],flush=True)
    for req in reqs:
        state=shim.with_image(req['state']);state_tokens=len(tok.encode(str(state),add_special_tokens=False));assert 30<=state_tokens<=600,(req['id'],state_tokens)
        for qid,q in req['questions'].items():
            active_id=req['id']+'.'+qid;before=len(calls)
            ans,n=shim.ANSWER[q['type']](state,q);assert len(calls)==before+1
            row={**calls[-1],**observations[-1],'id':active_id,'request_id':req['id'],'question_id':qid,'kind':q['type'],'primitive':q['type'],'state':str(state),'state_tokens':state_tokens,'instructions':q['instructions'],'question':q,'api_answer':ans,'labels':letters[:len(calls[-1]['label_ids'])],'temperature':0.85,'license':'CC BY-NC 4.0'}
            for key in ('zoo_only','multilingual','language','agent_shape','lowercase','explicit_criteria'):
                if key in req:row[key]=req[key]
            p=row['p_author'];raw=row['raw_logprobs'];z=np.asarray(raw)/0.85;independent=np.exp(z-z.max());independent/=independent.sum()
            assert np.max(np.abs(independent-p))<1e-12
            row['p_oracle']=p # compatibility alias, same oracle A, no second oracle
            row['argmax']=int(np.argmax(p));ordered=sorted(p,reverse=True);row['top2_margin']=ordered[0]-ordered[1]
            if q['type'] in ('choice','score'):
                assert list(ans['probabilities'].values())==[round(v,4) for v in p]
            if q['type']=='noul':
                py=min(max(p[0],1e-4),1-1e-4);value=1/(1+math.exp(-math.log(py/(1-py))/1.829074))
                row.update(p_yes=p[0],noul=value,noul_api=ans['noul']);assert round(value,4)==ans['noul']
            if q['type']=='score':
                value=sum(i*v for i,v in enumerate(p));row['expected_index']=value;assert round(value,4)==ans['score']
            if row.get('zoo_only'):assert 1500<=n<=2000
            else:assert n<=1024
            fx['rows'].append(row);save()
            print(active_id,n,'tokens',ans,flush=True)
            if not prepare: mx.clear_cache()
    rows=fx['rows'];choices=[r for r in rows if r['kind']=='choice' and not r.get('zoo_only')]
    summary={'requests':len(reqs),'rows':len(rows),'ordinary_choice':sum(2<=len(r['options'])<=26 for r in choices),
     'large_menus_10_26':sum(10<=len(r['options'])<=26 for r in choices),'choice_27_52':sum(27<=len(r['options'])<=52 for r in choices),
     'long_descriptions':sum(all(len(o['desc'].split())>5 for o in r['options']) for r in choices),
     'null_descriptions':sum(all(v is None for v in r['question']['criteria'].values()) for r in choices),
     'noul':sum(r['kind']=='noul' for r in rows),'noul_explicit':sum(r.get('explicit_criteria',False) for r in rows),
     'score':sum(r['kind']=='score' for r in rows),'score_10':sum(r['kind']=='score' and len(r['options'])==10 for r in rows),
     'multilingual':sum(r.get('multilingual',False) for r in rows),'languages':sorted(set(r['language'] for r in rows if r.get('multilingual'))),
     'agent_shape':sum(r.get('agent_shape',False) for r in rows),'zoo_only':sum(r.get('zoo_only',False) for r in rows),
     'state_token_range':[min(r['state_tokens'] for r in rows),max(r['state_tokens'] for r in rows)],
     'kit_prompt_token_range':[min(r['tokens'] for r in rows if not r.get('zoo_only')),max(r['tokens'] for r in rows if not r.get('zoo_only'))],
     'zoo_only_tokens':[r['tokens'] for r in rows if r.get('zoo_only')]}
    floors={'requests':20,'rows':56,'ordinary_choice':28,'large_menus_10_26':6,'choice_27_52':3,'long_descriptions':6,'null_descriptions':6,'noul':12,'noul_explicit':4,'score':10,'score_10':2,'multilingual':4,'agent_shape':4,'zoo_only':2}
    assert all(summary[k]>=v for k,v in floors.items()),summary
